verus! {
    // Helper function to check if a character is a vowel
    spec fn is_vowel(c: char) -> bool {
        c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
    }

    fn solve(input: Vec<char>) -> Vec<char>
        requires
            input.len() == 1,
            input[0] >= 'a' && input[0] <= 'z',
        ensures
            (is_vowel(input[0]) ==> result == vec!['v', 'o', 'w', 'e', 'l']) &&
            (!is_vowel(input[0]) ==> result == vec!['c', 'o', 'n', 's', 'o', 'n', 'a', 'n', 't']),
    {
        assert(input.len() == 1);
        let c = input[0];

        if is_vowel(c) {
            return vec!['v', 'o', 'w', 'e', 'l'];
        } else {
            return vec!['c', 'o', 'n', 's', 'o', 'n', 'a', 'n', 't'];
        }
    }
}
